    case 63:
      ACCEPT_TOKEN(sym_number);
      END_STATE();
    case 64:
      ACCEPT_TOKEN(sym_number);
      if (lookahead == '.') ADVANCE(66);
      if (lookahead == 'E' ||
          lookahead == 'e') ADVANCE(11);
      if (lookahead == 'X' ||
          lookahead == 'x') ADVANCE(14);
